import { API_URL, PASSWORD, expect, expectStatus, test, uniqueName } from "../../fixtures";

// Assumption: the other tenant's member account follows the seeded naming pattern
// ("member@<tenant>.test"). Adjust if the seed data uses a different address.
const GLOBEX_MEMBER_EMAIL = "member@globex.test";

test.describe("manage vendors", () => {
  test(
    "vendors from another tenant are invisible",
    { tag: "@VEN-07" },
    async ({ apiAs, request }) => {
      // Arrange: a vendor exists in the Globex Procurement tenant.
      const globexLogin = await expectStatus<{ access_token: string }>(
        await request.post(`${API_URL}/api/auth/login`, {
          data: { email: GLOBEX_MEMBER_EMAIL, password: PASSWORD },
        }),
        200,
      );
      const vendorName = uniqueName("Globex Vendor");
      const created = await expectStatus<{ id: string }>(
        await request.post(`${API_URL}/api/vendors`, {
          headers: { Authorization: `Bearer ${globexLogin.access_token}` },
          data: { name: vendorName, category: "software", contact_email: "ops@globex.test" },
        }),
        201,
      );

      // Act: the Northwind member requests that vendor by id.
      const member = await apiAs("member");
      const response = await member.get(`/api/vendors/${created.id}`);

      // Assert: the scenario requires 404 with vendor_not_found.
      const body = await expectStatus<{ error: { code: string } }>(response, 404);
      expect(body.error.code).toBe("vendor_not_found");
    },
  );
});
